@echo off
setlocal
set ROOT=%~dp0
set API_URL=http://127.0.0.1:8000
if not defined REALAI_API_URL set REALAI_API_URL=%API_URL%
if not defined REALAI_SELF_IMPROVE set REALAI_SELF_IMPROVE=1

where python >nul 2>&1
if errorlevel 1 (
  echo Python not found on PATH.
  exit /b 1
)

python -m realai.closed_loop --check-only
if errorlevel 1 (
  echo Server not ready. Start: python -m realai.server.app
  exit /b 1
)

if "%~1"=="" (
  python -m realai.closed_loop
) else (
  python -m realai.closed_loop --task "%~*"
)
endlocal

"""Command-line entrypoint for structured RealAI workflows."""

import argparse
import json
import os

try:
    import click
except ImportError:
    click = None

from realai.sdk.python.realai_client import RealAIClient


def _make_client(api_url):
    return RealAIClient(api_url=api_url)


def _chat_command(prompt, model, api_url):
    client = _make_client(api_url)
    response = client.chat(model=model, messages=[{'role': 'user', 'content': prompt}])
    print(response['choices'][0]['message']['content'])


def _json_command(value):
    print(json.dumps(value, indent=2, sort_keys=True))


if click is not None:
    @click.group()
    def cli():
        """RealAI CLI."""

    @cli.command()
    @click.argument('prompt')
    @click.option('--model', default='realai-1.0-instruct')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    def chat(prompt, model, api_url):
        """Send a prompt to the RealAI server."""
        _chat_command(prompt, model, api_url)

    @cli.command('health')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    def health(api_url):
        """Show server health."""
        _json_command(_make_client(api_url).health())

    @cli.command('models')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    def models(api_url):
        """List server models."""
        _json_command(_make_client(api_url).models())

    @cli.command('providers')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    def providers(api_url):
        """List configured providers."""
        _json_command(_make_client(api_url).providers())

    @cli.command('tasks')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    def tasks(api_url):
        """List persisted tasks."""
        _json_command(_make_client(api_url).list_tasks())

    @cli.command('build')
    @click.argument('task')
    @click.option('--api-url', envvar='REALAI_API_URL', default='http://localhost:8000')
    @click.option('--model', default=None)
    @click.option('--max-steps', default=20, type=int)
    def build(task, api_url, model, max_steps):
        """Run the local self-builder agent (repo tools + local GGUF)."""
        from realai.self_builder import SelfBuilder

        result = SelfBuilder(api_url=api_url, model=model, max_steps=max_steps).run(task)
        _json_command(result)
        raise SystemExit(0 if result.get('status') == 'done' else 1)

    def main(argv=None):
        """CLI entrypoint."""
        cli.main(args=argv, standalone_mode=False)
        return 0
else:
    def main(argv=None):
        """Fallback CLI entrypoint when click is unavailable."""
        parser = argparse.ArgumentParser(description='RealAI command-line interface.')
        parser.add_argument('command', choices=['chat', 'health', 'models', 'providers', 'tasks'])
        parser.add_argument('prompt', nargs='?')
        parser.add_argument('--model', default='realai-1.0')
        parser.add_argument('--api-url', default=os.environ.get('REALAI_API_URL', 'http://localhost:8000'))
        args = parser.parse_args(argv)
        if args.command == 'chat':
            _chat_command(args.prompt or '', args.model, args.api_url)
        elif args.command == 'health':
            _json_command(_make_client(args.api_url).health())
        elif args.command == 'models':
            _json_command(_make_client(args.api_url).models())
        elif args.command == 'providers':
            _json_command(_make_client(args.api_url).providers())
        elif args.command == 'tasks':
            _json_command(_make_client(args.api_url).list_tasks())
        return 0


if __name__ == '__main__':
    raise SystemExit(main())

"""Structured RealAI inference server."""

import warnings

# Suppress the benign but noisy RuntimeWarning that appears on Windows (and sometimes
# other platforms) when you run:
#     python -m realai.server.app
# It is emitted by runpy because the package 'realai.server' gets imported in one form
# and then the module is executed under a slightly different name. Completely harmless
# for our use case — we just don't want it polluting the user's terminal every startup.
warnings.filterwarnings(
    "ignore",
    message=r".*found in sys.modules after import of package 'realai\.server'.*",
    category=RuntimeWarning,
)

import json
from wsgiref.simple_server import make_server

from .router import dispatch_request
from .playground import get_playground_html

try:
    from fastapi import FastAPI, HTTPException
    from fastapi.responses import HTMLResponse, Response, StreamingResponse
    from pydantic import BaseModel
except ImportError:
    FastAPI = None
    HTTPException = None
    Response = None
    HTMLResponse = None
    BaseModel = None


class _ASGIApplication(object):
    """Minimal ASGI fallback used when FastAPI is unavailable."""

    async def __call__(self, scope, receive, send):
        if scope.get('type') != 'http':
            return

        body = b''
        more_body = True
        while more_body:
            message = await receive()
            if message.get('type') != 'http.request':
                continue
            body += message.get('body', b'')
            more_body = message.get('more_body', False)

        payload = None
        if body:
            try:
                payload = json.loads(body.decode('utf-8'))
            except ValueError:
                await _send_json(send, 400, {'error': {'message': 'Request body must be valid JSON.'}})
                return

        status_code, data, content_type = dispatch_request(
            scope.get('method', 'GET'),
            scope.get('path', '/'),
            payload,
        )
        if content_type.startswith('application/json'):
            await _send_json(send, status_code, data)
        else:
            await _send_text(send, status_code, data, content_type)


async def _send_json(send, status_code, data):
    body = json.dumps(data).encode('utf-8')
    await send({
        'type': 'http.response.start',
        'status': status_code,
        'headers': [
            (b'content-type', b'application/json'),
            (b'content-length', str(len(body)).encode('ascii')),
        ],
    })
    await send({'type': 'http.response.body', 'body': body})


async def _send_text(send, status_code, data, content_type):
    body = data.encode('utf-8')
    await send({
        'type': 'http.response.start',
        'status': status_code,
        'headers': [
            (b'content-type', content_type.encode('utf-8')),
            (b'content-length', str(len(body)).encode('ascii')),
        ],
    })
    await send({'type': 'http.response.body', 'body': body})


if FastAPI is not None and BaseModel is not None:
    class ChatRequest(BaseModel):
        """Chat completion request."""

        model: str
        messages: list
        temperature: float = 0.2
        max_tokens: int = 1024


    class EmbeddingRequest(BaseModel):
        """Embedding request."""

        model: str
        input: list

    class ImageGenerationRequest(BaseModel):
        prompt: str
        size: str = '1024x1024'
        n: int = 1

    class AudioTranscriptionRequest(BaseModel):
        file: str
        language: str = 'en'

    class AudioSpeechRequest(BaseModel):
        input: str
        voice: str = 'alloy'

    class MemoryStoreRequest(BaseModel):
        user_id: str = 'anonymous'
        agent_id: str = 'default'
        content: str
        metadata: dict = {}

    class MemoryInspectRequest(BaseModel):
        user_id: str = 'anonymous'
        agent_id: str = 'default'

    class TaskRequest(BaseModel):
        task: str
        context: str = ''


    app = FastAPI(title='RealAI Provider')

    def _dispatch_json(method, path, payload=None):
        try:
            status, data, _content_type = dispatch_request(method, path, payload)
            if status >= 400 and HTTPException is not None:
                message = data.get('error', {}).get('message', 'Request failed')
                if status >= 500:
                    message = 'Internal server error'
                raise HTTPException(status_code=status, detail=message)
            return data
        except Exception as exc:
            if HTTPException is not None and isinstance(exc, HTTPException):
                raise
            logger.exception('Unhandled app dispatch exception: %s', exc)
            if HTTPException is not None:
                raise HTTPException(status_code=500, detail='Internal server error')
            return {'error': {'message': 'Internal server error'}}

    @app.post('/v1/chat/completions')
    def chat(request: ChatRequest):
        payload = request.dict()
        if payload.get('stream'):
            def stream_generator():
                # Get full response (backends are sync; simulate OpenAI SSE chunks)
                full_resp = _dispatch_json('POST', '/v1/chat/completions', {**payload, 'stream': False})
                text = ''
                try:
                    text = full_resp.get('choices', [{}])[0].get('message', {}).get('content', '')
                except Exception:
                    text = 'Streaming response unavailable.'
                # Yield in OpenAI-compatible SSE format
                for i, chunk in enumerate(text.split(' ')):
                    if chunk:
                        delta = {'choices': [{'index': 0, 'delta': {'content': chunk + ' '}, 'finish_reason': None}]}
                        yield f"data: {json.dumps(delta)}\n\n"
                # Final chunk
                yield 'data: {"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}\n\n'
                yield 'data: [DONE]\n\n'
            return StreamingResponse(stream_generator(), media_type='text/event-stream')
        return _dispatch_json('POST', '/v1/chat/completions', payload)

    @app.post('/v1/embeddings')
    def embeddings(request: EmbeddingRequest):
        return _dispatch_json('POST', '/v1/embeddings', request.dict())

    @app.get('/v1/models')
    def models():
        return _dispatch_json('GET', '/v1/models')

    @app.get('/v1/models/{model_id}')
    def model_details(model_id: str):
        return _dispatch_json('GET', '/v1/models/{0}'.format(model_id))

    @app.get('/v1/providers')
    def providers():
        return _dispatch_json('GET', '/v1/providers')

    @app.get('/v1/providers/{provider_id}')
    def provider_details(provider_id: str):
        return _dispatch_json('GET', '/v1/providers/{0}'.format(provider_id))

    @app.post('/v1/images/generations')
    def image_generations(request: ImageGenerationRequest):
        return _dispatch_json('POST', '/v1/images/generations', request.dict())

    @app.post('/v1/audio/transcriptions')
    def audio_transcriptions(request: AudioTranscriptionRequest):
        return _dispatch_json('POST', '/v1/audio/transcriptions', request.dict())

    @app.post('/v1/audio/speech')
    def audio_speech(request: AudioSpeechRequest):
        return _dispatch_json('POST', '/v1/audio/speech', request.dict())

    @app.post('/v1/memory/store')
    def memory_store(request: MemoryStoreRequest):
        return _dispatch_json('POST', '/v1/memory/store', request.dict())

    @app.post('/v1/memory/inspect')
    def memory_inspect(request: MemoryInspectRequest):
        return _dispatch_json('POST', '/v1/memory/inspect', request.dict())

    @app.post('/v1/memory/clear')
    def memory_clear(request: MemoryInspectRequest):
        return _dispatch_json('POST', '/v1/memory/clear', request.dict())

    @app.get('/v1/tools')
    def tools():
        return _dispatch_json('GET', '/v1/tools')

    @app.post('/v1/tasks')
    def tasks_create(request: TaskRequest):
        return _dispatch_json('POST', '/v1/tasks', request.dict())

    @app.get('/v1/tasks')
    def tasks_list():
        return _dispatch_json('GET', '/v1/tasks')

    @app.get('/v1/tasks/{task_id}')
    def tasks_get(task_id: str):
        return _dispatch_json('GET', '/v1/tasks/{0}'.format(task_id))

    @app.get('/health')
    def health():
        return _dispatch_json('GET', '/health')

    @app.get('/metrics')
    def metrics():
        status_code, data, content_type = dispatch_request('GET', '/metrics')
        if Response is not None:
            return Response(content=data, media_type=content_type)
        return data

    _FAVICON_SVG = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">'
        '<rect fill="#2563eb" width="32" height="32" rx="8"/></svg>'
    )

    @app.get('/favicon.ico')
    def favicon():
        if Response is not None:
            return Response(content=_FAVICON_SVG, media_type='image/svg+xml')
        return _FAVICON_SVG

    @app.get('/ui')
    def ui():
        if HTMLResponse is not None:
            return HTMLResponse(content=get_playground_html())
        return get_playground_html()

    @app.get('/')
    def root():
        return ui()
else:
    app = _ASGIApplication()


def wsgi_app(environ, start_response):
    """WSGI entrypoint for the structured server."""
    method = environ.get('REQUEST_METHOD', 'GET')
    path = environ.get('PATH_INFO', '/')
    payload = None
    content_length = environ.get('CONTENT_LENGTH') or '0'
    try:
        body_size = int(content_length)
    except ValueError:
        body_size = 0
    if body_size > 0:
        raw_body = environ['wsgi.input'].read(body_size)
        if raw_body:
            try:
                payload = json.loads(raw_body.decode('utf-8'))
            except ValueError:
                body = json.dumps({'error': {'message': 'Request body must be valid JSON.'}}).encode('utf-8')
                start_response('400 Bad Request', [
                    ('Content-Type', 'application/json'),
                    ('Content-Length', str(len(body))),
                ])
                return [body]

    if path == '/favicon.ico':
        favicon_svg = (
            b'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">'
            b'<rect fill="#2563eb" width="32" height="32" rx="8"/>'
            b'</svg>'
        )
        start_response('200 OK', [
            ('Content-Type', 'image/svg+xml'),
            ('Content-Length', str(len(favicon_svg))),
            ('Cache-Control', 'public, max-age=86400'),
        ])
        return [favicon_svg]

    # Serve the beautiful local playground UI
    if path in ('/', '/ui', '/playground'):
        html = get_playground_html()
        body = html.encode('utf-8')
        start_response('200 OK', [
            ('Content-Type', 'text/html; charset=utf-8'),
            ('Content-Length', str(len(body))),
            ('Cache-Control', 'no-store'),
        ])
        return [body]

    status_code, data, content_type = dispatch_request(method, path, payload)
    body = json.dumps(data).encode('utf-8') if content_type.startswith('application/json') else data.encode('utf-8')
    start_response('{0} {1}'.format(status_code, _reason_phrase(status_code)), [
        ('Content-Type', content_type),
        ('Content-Length', str(len(body))),
    ])
    return [body]


def _reason_phrase(status_code):
    """Return a simple HTTP reason phrase."""
    if status_code == 200:
        return 'OK'
    if status_code == 400:
        return 'Bad Request'
    if status_code == 404:
        return 'Not Found'
    return 'Internal Server Error'


def main(host='0.0.0.0', port=8000):
    """Run the structured WSGI server."""
    try:
        from .native_bootstrap import apply_native_bootstrap

        boot = apply_native_bootstrap()
        if boot.get("status") == "published":
            print('[realai] Native weights bootstrapped:', boot.get('gguf'))
    except Exception as exc:
        print('[realai] Native bootstrap skipped:', exc)

    httpd = make_server(host, int(port), wsgi_app)
    print('Structured RealAI server listening on http://{0}:{1}'.format(host, port))
    print('→ Open the local Web UI: http://{0}:{1}/ui'.format(host, port))
    print('Press Ctrl+C to stop.')
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print('\n[realai] Server stopped by user (Ctrl+C).')
        try:
            httpd.server_close()
        except Exception:
            pass


if __name__ == '__main__':
    main()

"""Routing helpers for the structured RealAI server."""

import time

from .config import get_model_config, list_model_objects, list_models, load_settings
from .embeddings import embed
from .inference import chat_completion
from .logging_utils import setup_logging
from .memory_store import MEMORY
from .metrics import CONTENT_TYPE_LATEST, generate_latest
from .orchestration import TASKS
from .providers import get_provider, list_providers, provider_for_model
from .tools_runtime import TOOLS

logger = setup_logging()


class RequestValidationError(Exception):
    """Raised when a request body is invalid."""

    def __init__(self, message, status_code=400):
        super(RequestValidationError, self).__init__(message)
        self.status_code = status_code


def _require_dict(payload):
    if not isinstance(payload, dict):
        raise RequestValidationError('Request body must be a JSON object.')
    return payload


def _require_messages(messages):
    if not isinstance(messages, list) or not messages:
        raise RequestValidationError('messages must be a non-empty list.')
    for item in messages:
        if not isinstance(item, dict) or 'role' not in item or 'content' not in item:
            raise RequestValidationError('Each message must include role and content.')
    return messages


def _require_input_texts(values):
    if isinstance(values, str):
        return [values]
    if not isinstance(values, list) or not values:
        raise RequestValidationError('input must be a non-empty string or list of strings.')
    for value in values:
        if not isinstance(value, str):
            raise RequestValidationError('All embedding inputs must be strings.')
    return values


def _coalesce_model(payload, model_type='chat'):
    model_name = payload.get('model')
    if model_name:
        return model_name
    settings = load_settings()
    return settings.default_chat_model if model_type == 'chat' else settings.default_embedding_model


def _coerce_float(name, value, default, min_value=0.0, max_value=2.0):
    if value is None:
        return default
    try:
        val = float(value)
    except (TypeError, ValueError):
        raise RequestValidationError('{0} must be a number.'.format(name))
    if val < min_value or val > max_value:
        raise RequestValidationError('{0} must be between {1} and {2}.'.format(name, min_value, max_value))
    return val


def _coerce_int(name, value, default, min_value=1):
    if value is None:
        return default
    try:
        val = int(value)
    except (TypeError, ValueError):
        raise RequestValidationError('{0} must be an integer.'.format(name))
    if val < min_value:
        raise RequestValidationError('{0} must be >= {1}.'.format(name, min_value))
    return val


def health_response():
    """Return a health payload for the structured server."""
    settings = load_settings()
    return {
        'status': 'ok',
        'provider': settings.provider,
        'profile': settings.profile,
        'available_models': list_models(),
        'providers': list_providers(),
    }


def handle_chat_request(payload):
    """Handle a chat completions request."""
    payload = _require_dict(payload)
    model_name = _coalesce_model(payload, model_type='chat')
    messages = _require_messages(payload.get('messages'))
    messages_for_inference = list(messages)
    temperature = _coerce_float('temperature', payload.get('temperature', 0.2), 0.2)
    max_tokens = _coerce_int('max_tokens', payload.get('max_tokens', 1024), 1024)
    stream = bool(payload.get('stream', False))
    tools = payload.get('tools', [])
    if tools and not isinstance(tools, list):
        raise RequestValidationError('tools must be a list when provided.')

    retrieved = []
    user_id = payload.get('user_id', 'anonymous')
    agent_id = payload.get('agent_id', 'default')
    if messages:
        retrieved = MEMORY.retrieve(user_id, agent_id, str(messages[-1].get('content', '')), top_k=3)
    memory_context = '\n'.join(item.get('summary', '') for item in retrieved if item.get('summary'))
    if memory_context:
        messages_for_inference.append({'role': 'system', 'content': 'Relevant memory: {0}'.format(memory_context)})

    try:
        resp = chat_completion(
            model_name,
            messages_for_inference,
            temperature=temperature,
            max_tokens=max_tokens,
        )
        # Basic automatic tool calling execution (if tools provided in request)
        if tools:
            text = resp.get('choices', [{}])[0].get('message', {}).get('content', '')
            # Support custom TOOL: format from self-builder style or simple execution
            if 'TOOL:' in text.upper() or any(t.get('function', {}).get('name') for t in tools):
                # Execute first matching tool for demo (repo tools or registered)
                executed = False
                for tool in tools:
                    name = tool.get('function', {}).get('name') or tool.get('name')
                    if name in ('file_read', 'read_file', 'grep', 'run_terminal_command'):
                        # Use repo tool handlers for automatic execution
                        try:
                            from ..repo_tools import REPO_TOOL_HANDLERS
                            args = tool.get('function', {}).get('arguments') or {}
                            if isinstance(args, str):
                                import json
                                args = json.loads(args)
                            handler = REPO_TOOL_HANDLERS.get(name) or REPO_TOOL_HANDLERS.get(name.replace('_', ''))
                            if handler:
                                result = handler(**args)
                                # Inject tool result as follow-up (for multi-turn feel)
                                resp['choices'][0]['message']['content'] = text + f"\n\n[Tool {name} executed: {str(result)[:300]}]"
                                executed = True
                                break
                        except Exception as tool_exc:
                            logger.warning('Tool auto-exec failed for %s: %s', name, tool_exc)
                if not executed:
                    resp['choices'][0]['message']['content'] = text + "\n\n[Tools provided but no auto-executor matched; see /v1/tools]"
        try:
            assistant_text = (
                resp.get('choices', [{}])[0].get('message', {}).get('content', '') or ''
            ).strip()
            for msg in reversed(messages):
                if msg.get('role') == 'user':
                    user_text = str(msg.get('content', '')).strip()
                    if user_text:
                        MEMORY.add(
                            user_id,
                            agent_id,
                            user_text[:2000],
                            metadata={'source': 'chat', 'model': model_name},
                        )
                    break
            if assistant_text:
                MEMORY.add(
                    user_id,
                    agent_id,
                    assistant_text[:2000],
                    metadata={'source': 'chat_reply', 'model': model_name},
                )
        except Exception as mem_exc:
            logger.debug('Memory store after chat skipped: %s', mem_exc)
        return resp
    except Exception as exc:
        logger.warning('Structured chat fallback used for %s: %s', model_name, exc)
        return {
            'id': 'chatcmpl-realai-fallback',
            'model': model_name,
            'choices': [
                {
                    'index': 0,
                    'message': {'role': 'assistant', 'content': 'Fallback response: local model runtime unavailable.'},
                    'finish_reason': 'stop',
                }
            ],
            'backend': 'structured-fallback',
        }


def handle_embeddings_request(payload):
    """Handle an embeddings request."""
    payload = _require_dict(payload)
    model_name = _coalesce_model(payload, model_type='embedding')
    inputs = _require_input_texts(payload.get('input'))
    cfg = get_model_config(model_name)
    vectors = embed(model_name, inputs)
    return {
        'object': 'list',
        'model': model_name,
        'dimensions': cfg.get('embedding_dimensions', len(vectors[0]) if vectors else 0),
        'data': [
            {
                'object': 'embedding',
                'index': index,
                'embedding': vector,
            }
            for index, vector in enumerate(vectors)
        ],
    }


def handle_images_request(payload):
    payload = _require_dict(payload)
    prompt = payload.get('prompt')
    if not isinstance(prompt, str) or not prompt.strip():
        raise RequestValidationError('prompt is required.')
    n = _coerce_int('n', payload.get('n', 1), 1)
    size = payload.get('size', '1024x1024')
    return {
        'created': int(time.time()),
        'data': [
            {'url': 'https://realai.local/generated/{0}.png'.format(index), 'revised_prompt': prompt, 'size': size}
            for index in range(n)
        ],
    }


def handle_audio_transcription(payload):
    payload = _require_dict(payload)
    audio_file = payload.get('file') or payload.get('audio_file')
    if not isinstance(audio_file, str) or not audio_file:
        raise RequestValidationError('file is required.')
    return {
        'text': 'Transcription placeholder for {0}'.format(audio_file),
        'language': payload.get('language', 'en'),
    }


def handle_audio_speech(payload):
    payload = _require_dict(payload)
    text = payload.get('input') or payload.get('text')
    if not isinstance(text, str) or not text.strip():
        raise RequestValidationError('input is required.')
    return {
        'audio_url': 'https://realai.local/audio/speech.wav',
        'voice': payload.get('voice', 'alloy'),
        'format': payload.get('format', 'wav'),
    }


def handle_models_list():
    return {'object': 'list', 'data': list_model_objects()}


def handle_model_read(path):
    marker = '/v1/models/'
    if marker not in path:
        raise RequestValidationError('Invalid model path.')
    model_id = path.split(marker, 1)[1]
    if not model_id:
        raise RequestValidationError('model_id is required.')
    cfg = get_model_config(model_id)
    return {
        'id': model_id,
        'object': 'model',
        'owned_by': cfg.get('owned_by', 'realai'),
        'provider': cfg.get('provider', load_settings().provider),
        'type': cfg.get('type', 'chat'),
        'backend': cfg.get('backend', 'unknown'),
        'context_length': cfg.get('context_length'),
        'embedding_dimensions': cfg.get('embedding_dimensions'),
        'capabilities': cfg.get('capabilities', []),
        'path': cfg.get('path'),
    }


