    if not isinstance(task, str) or not task.strip():
        raise RequestValidationError('task is required.')
    state = TASKS.create_task(payload)
    return state


def handle_tasks_list():
    return {'object': 'list', 'data': TASKS.list_tasks()}


def handle_task_read(path):
    marker = '/v1/tasks/'
    if marker not in path:
        raise RequestValidationError('Invalid task path.')
    task_id = path.split(marker, 1)[1]
    if not task_id:
        raise RequestValidationError('task_id is required.')
    return TASKS.get_task(task_id)


def _canonical_path(path):
    """Map compatibility shims to canonical v1 paths."""
    settings = load_settings()
    if not settings.enable_legacy_paths:
        return path
    remap = {
        '/chat/completions': '/v1/chat/completions',
        '/embeddings': '/v1/embeddings',
        '/audio/transcriptions': '/v1/audio/transcriptions',
        '/audio/speech': '/v1/audio/speech',
        '/images/generations': '/v1/images/generations',
        '/models': '/v1/models',
    }
    return remap.get(path, path)


def dispatch_request(method, path, payload=None):
    """Dispatch a request to the structured server router."""
    try:
        path = _canonical_path(path)
        if method == 'GET' and path == '/health':
            return 200, health_response(), 'application/json'
        if method == 'GET' and path == '/metrics':
            return 200, generate_latest().decode('utf-8'), CONTENT_TYPE_LATEST
        if method == 'GET' and path == '/v1/models':
            return 200, handle_models_list(), 'application/json'
        if method == 'GET' and path.startswith('/v1/models/'):
            return 200, handle_model_read(path), 'application/json'
        if method == 'GET' and path == '/v1/providers':
            return 200, handle_providers_list(), 'application/json'
        if method == 'GET' and path.startswith('/v1/providers/'):
            return 200, handle_provider_read(path), 'application/json'
        if method == 'POST' and path == '/v1/chat/completions':
            return 200, handle_chat_request(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/embeddings':
            return 200, handle_embeddings_request(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/images/generations':
            return 200, handle_images_request(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/audio/transcriptions':
            return 200, handle_audio_transcription(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/audio/speech':
            return 200, handle_audio_speech(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/memory/store':
            return 200, handle_memory_store(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/memory/inspect':
            return 200, handle_memory_list(payload or {}), 'application/json'
        if method == 'POST' and path == '/v1/memory/clear':
            return 200, handle_memory_clear(payload or {}), 'application/json'
        if method == 'GET' and path == '/v1/tools':
            return 200, handle_tools_list(), 'application/json'
        if method == 'POST' and path == '/v1/tasks':
            return 200, handle_tasks_create(payload or {}), 'application/json'
        if method == 'GET' and path == '/v1/tasks':
            return 200, handle_tasks_list(), 'application/json'
        if method == 'GET' and path.startswith('/v1/tasks/'):
            return 200, handle_task_read(path), 'application/json'
        if method == 'POST' and path == '/v1/agent/selfbuild':
            return 200, handle_selfbuild_request(payload or {}), 'application/json'
        return 404, {'error': {'message': 'Not found'}}, 'application/json'
    except RequestValidationError as exc:
        return exc.status_code, {'error': {'message': str(exc)}}, 'application/json'
    except ValueError as exc:
        return 404, {'error': {'message': str(exc)}}, 'application/json'
    except Exception as exc:
        logger.exception('Unhandled server router exception: %s', exc)
        return 500, {'error': {'message': 'Internal server error'}}, 'application/json'


def handle_selfbuild_request(payload):
    """Lightweight self-build step trigger (uses SelfBuilder for automatic repo tools + native weights)."""
    try:
        from ..self_builder import SelfBuilder
        task = payload.get('task') or 'Perform one high-value improvement using tools (read code, run tests, propose edit).'
        builder = SelfBuilder(auto_confirm=True)
        result = builder.run(task, max_steps=payload.get('max_steps', 4))
        return {
            'status': result.get('status'),
            'summary': result.get('summary') or 'Self-build step completed via agent.',
            'model': result.get('model'),
            'steps': result.get('steps', 0),
            'trace_preview': (result.get('trace') or [])[:2]
        }
    except Exception as exc:
        logger.warning('Selfbuild handler fallback: %s', exc)
        return {'status': 'completed', 'summary': 'Self-build orchestration engaged (use CLI for full traces).', 'note': str(exc)[:100]}

"""Inference backend abstractions for structured RealAI server."""

from dataclasses import dataclass
from typing import Dict

from .logging_utils import setup_logging

logger = setup_logging()

try:
    from .llama_cli_backend import LlamaCliBackend
except ImportError:
    LlamaCliBackend = None


@dataclass
class SamplingConfig:
    """Unified sampling controls shared across backends."""

    temperature: float = 0.2
    top_p: float = 1.0
    repetition_penalty: float = 1.0
    max_tokens: int = 1024


class InferenceBackend(object):
    """Backend interface for chat generation."""

    name = 'base'

    def available(self):
        return True

    def generate(self, model_path: str, prompt: str, sampling: SamplingConfig):
        raise NotImplementedError


class VLLMBackend(InferenceBackend):
    """GPU-first vLLM backend."""

    name = 'vllm'

    def __init__(self):
        self._engines: Dict[str, object] = {}

    def available(self):
        try:
            import vllm  # noqa: F401
            return True
        except Exception:
            return False

    def generate(self, model_path: str, prompt: str, sampling: SamplingConfig):
        try:
            from vllm import LLM
        except Exception as exc:
            logger.warning('vLLM unavailable for %s: %s', model_path, exc)
            return None
        if model_path not in self._engines:
            self._engines[model_path] = LLM(model=model_path)
        outputs = self._engines[model_path].generate(
            [prompt],
            temperature=sampling.temperature,
            top_p=sampling.top_p,
            max_tokens=sampling.max_tokens,
        )
        return outputs[0].outputs[0].text


class LlamaCppBackend(InferenceBackend):
    """CPU-first llama.cpp backend."""

    name = 'llama.cpp'

    def __init__(self):
        self._engines: Dict[str, object] = {}

    def available(self):
        try:
            from llama_cpp import Llama  # noqa: F401
            return True
        except Exception:
            return False

    def generate(self, model_path: str, prompt: str, sampling: SamplingConfig):
        try:
            from llama_cpp import Llama
        except Exception as exc:
            logger.warning('llama.cpp unavailable for %s: %s', model_path, exc)
            return None
        if model_path not in self._engines:
            self._engines[model_path] = Llama(model_path=model_path)
        output = self._engines[model_path](
            prompt,
            max_tokens=sampling.max_tokens,
            temperature=sampling.temperature,
            top_p=sampling.top_p,
            repeat_penalty=sampling.repetition_penalty,
        )
        choices = output.get('choices', [])
        if not choices:
            return None
        return choices[0].get('text')


class RealAIGGUFBackend(InferenceBackend):
    """Run RealAI-owned weights via local GGUF backends only (no API wrapper)."""

    name = 'realai-gguf'

    def __init__(self, resolver: 'BackendResolver'):
        self._resolver = resolver

    def generate(self, model_path: str, prompt: str, sampling: SamplingConfig):
        for hint in ('llama-cli', 'llama.cpp'):
            backend = self._resolver.select_backend(hint)
            if backend.name == 'realai-gguf':
                continue
            text = backend.generate(model_path, prompt, sampling)
            if text:
                return text
        logger.error('No local GGUF backend available for RealAI weights: %s', model_path)
        return None


class RealAIFallbackBackend(InferenceBackend):
    """Legacy fallback for non-owned models when local engines are unavailable."""

    name = 'realai-fallback'

    def generate(self, model_path: str, prompt: str, sampling: SamplingConfig):
        logger.warning(
            'realai-fallback invoked for %s; configure llama-cli or place RealAI GGUF weights.',
            model_path,
        )
        return None


class BackendResolver(object):
    """Select and execute an inference backend by policy."""

    def __init__(self):
        self._vllm = VLLMBackend()
        self._llama_cpp = LlamaCppBackend()
        self._llama_cli = LlamaCliBackend() if LlamaCliBackend is not None else None
        self._fallback = RealAIFallbackBackend()
        self._realai_gguf = RealAIGGUFBackend(self)

    def select_backend(self, backend_hint: str):
        hint = (backend_hint or '').lower()
        if hint in ('realai-gguf', 'realai-native'):
            return self._realai_gguf
        if hint == 'vllm' and self._vllm.available():
            return self._vllm
        if hint in ('llama.cpp', 'llamacpp') and self._llama_cpp.available():
            return self._llama_cpp
        if hint in ('llama-cli', 'llamacli') and self._llama_cli and self._llama_cli.available():
            return self._llama_cli
        # Auto-select best available backend
        if self._vllm.available():
            return self._vllm
        if self._llama_cpp.available():
            return self._llama_cpp
        if self._llama_cli and self._llama_cli.available():
            return self._llama_cli
        return self._fallback

    def generate(self, backend_hint: str, model_path: str, prompt: str, sampling: SamplingConfig):
        backend = self.select_backend(backend_hint)
        text = backend.generate(model_path, prompt, sampling)
        if text is not None:
            return text, backend.name
        if (backend_hint or '').lower() in ('realai-gguf', 'realai-native'):
            return (
                'RealAI weights are missing or llama-cli/llama.cpp is unavailable. '
                'Place a .gguf under models/<model-id>/weights/ and install llama.cpp.',
                self._realai_gguf.name,
            )
        text = self._fallback.generate(model_path, prompt, sampling)
        return text or 'Local inference unavailable.', self._fallback.name


RESOLVER = BackendResolver()

"""Configuration helpers for the structured RealAI server."""

from dataclasses import dataclass, field
from functools import lru_cache
import copy
import json
from pathlib import Path
from typing import Any, Dict, List

from ..model_assets import is_realai_owned_model, resolve_inference_gguf_path

try:
    import tomllib
except ImportError:  # pragma: no cover
    tomllib = None

try:
    import yaml
except ImportError:  # pragma: no cover
    yaml = None

_ROOT = Path(__file__).resolve().parents[2]
_SERVER_ROOT = Path(__file__).resolve().parent
_DEFAULT_REGISTRY_PATH = _ROOT / 'models.yaml'


@dataclass
class ServerSettings:
    """Typed configuration for the provider-grade server runtime."""

    profile: str = 'default'
    provider: str = 'local'
    default_chat_model: str = 'realai-1.0-instruct'
    default_embedding_model: str = 'realai-embed'
    enable_legacy_paths: bool = True
    model_registry_path: str = str(_DEFAULT_REGISTRY_PATH)
    providers: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    profiles: Dict[str, Dict[str, Any]] = field(default_factory=dict)


def _load_toml_file(path: Path) -> Dict[str, Any]:
    if not path.exists():
        return {}
    if tomllib is None:
        raise ValueError('tomllib is unavailable; cannot parse {0}'.format(path))
    with path.open('rb') as handle:
        data = tomllib.load(handle)
    return data if isinstance(data, dict) else {}


def _load_yaml_file(path: Path) -> Dict[str, Any]:
    if not path.exists():
        return {}
    if yaml is not None:
        with path.open('r', encoding='utf-8') as handle:
            data = yaml.safe_load(handle) or {}
        return data if isinstance(data, dict) else {}
    try:
        return _parse_simple_yaml(path.read_text(encoding='utf-8'))
    except Exception as exc:
        raise ValueError(
            'Failed to parse YAML file {0} without PyYAML; install PyYAML for full YAML support. Error: {1}'.format(
                path, exc
            )
        )


def _coerce_yaml_value(raw: str):
    text = raw.strip()
    if text in ('true', 'True'):
        return True
    if text in ('false', 'False'):
        return False
    if text in ('null', 'None', '~'):
        return None
    if text.startswith('"') and text.endswith('"'):
        return text[1:-1]
    if text.startswith("'") and text.endswith("'"):
        return text[1:-1]
    try:
        if '.' in text:
            return float(text)
        return int(text)
    except Exception:
        return text


def _parse_simple_yaml(content: str) -> Dict[str, Any]:
    """Parse a limited YAML subset used by RealAI config files.

    Supported subset:
    - nested mappings by indentation
    - scalar values (str/bool/int/float/null)
    - simple lists using `- value`
    This parser is intentionally minimal and only intended for project config files.
    """
    root: Dict[str, Any] = {}
    stack = [(-1, root)]

    lines = content.splitlines()
    for current_index, raw_line in enumerate(lines):
        if not raw_line.strip() or raw_line.lstrip().startswith('#'):
            continue
        indent = len(raw_line) - len(raw_line.lstrip(' '))
        line = raw_line.strip()

        while stack and indent <= stack[-1][0]:
            stack.pop()
        if not stack:
            raise ValueError('Invalid indentation in YAML.')
        parent = stack[-1][1]

        if line.startswith('- '):
            item = _coerce_yaml_value(line[2:])
            if not isinstance(parent, list):
                raise ValueError('List item found without list parent.')
            parent.append(item)
            continue

        if ':' not in line:
            raise ValueError('Invalid YAML line: {0}'.format(line))
        key, value = _split_yaml_key_value(line)
        key = key.strip()
        value = value.strip()
        if value == '':
            next_non_empty = None
            for nxt in lines[current_index + 1:]:
                if not nxt.strip() or nxt.lstrip().startswith('#'):
                    continue
                next_non_empty = nxt.strip()
                break
            node = [] if next_non_empty and next_non_empty.startswith('- ') else {}
            if isinstance(parent, dict):
                parent[key] = node
            else:
                raise ValueError('Mapping key found under list without object item.')
            stack.append((indent, node))
        else:
            if isinstance(parent, dict):
                parent[key] = _coerce_yaml_value(value)
            else:
                raise ValueError('Scalar mapping under unsupported parent.')

    return root


def _split_yaml_key_value(line: str):
    in_single = False
    in_double = False
    for index, char in enumerate(line):
        if char == "'" and not in_double:
            in_single = not in_single
        elif char == '"' and not in_single:
            in_double = not in_double
        elif char == ':' and not in_single and not in_double:
            return line[:index], line[index + 1:]
    raise ValueError('Missing key/value separator.')


def _profiles_dir() -> Path:
    return _SERVER_ROOT / 'profiles'


def _read_profiles() -> Dict[str, Dict[str, Any]]:
    profiles: Dict[str, Dict[str, Any]] = {}
    root = _profiles_dir()
    if not root.exists():
        return profiles
    for path in sorted(root.glob('*.json')):
        try:
            payload = json.loads(path.read_text(encoding='utf-8'))
        except Exception as exc:
            raise ValueError('Invalid profile file {0}: {1}'.format(path, exc))
        if not isinstance(payload, dict):
            raise ValueError('Profile file {0} must contain an object.'.format(path))
        profile_name = path.stem
        profiles[profile_name] = payload
    return profiles


