def _normalize_model_type(raw_type: Any) -> str:
    text = str(raw_type or 'chat').strip().lower()
    if text == 'embeddings':
        return 'embedding'
    return text


def _normalize_model_entry(model_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    normalized = copy.deepcopy(payload)
    normalized['id'] = model_id
    normalized['type'] = _normalize_model_type(normalized.get('type', 'chat'))
    owned = str(normalized.get('owned_by', '')).lower() == 'realai' or str(model_id).startswith('realai-')
    if normalized['type'] == 'chat':
        if owned and model_id not in ('realai-embed',):
            normalized.setdefault('backend', 'realai-gguf')
        else:
            normalized.setdefault('backend', 'llama-cli')
    else:
        normalized.setdefault('backend', 'deterministic')
    normalized.setdefault('path', model_id)
    normalized.setdefault('owned_by', 'realai')
    normalized.setdefault('capabilities', ['embedding'] if normalized['type'] == 'embedding' else ['chat'])
    if normalized['type'] == 'embedding':
        normalized.setdefault('embedding_dimensions', 64)
    return normalized


def _coerce_registry(data: Any) -> Dict[str, Dict[str, Any]]:
    if isinstance(data, dict) and 'models' in data:
        data = data.get('models')

    if isinstance(data, list):
        registry = {}
        for item in data:
            if not isinstance(item, dict):
                raise ValueError('Each model entry must be an object.')
            model_id = str(item.get('id', '')).strip()
            if not model_id:
                raise ValueError('Each model entry must include an id.')
            registry[model_id] = _normalize_model_entry(model_id, item)
        return registry

    if isinstance(data, dict):
        registry = {}
        for model_id, payload in data.items():
            if not isinstance(payload, dict):
                raise ValueError('Model registry entries must be objects.')
            registry[str(model_id)] = _normalize_model_entry(str(model_id), payload)
        return registry

    raise ValueError('Model registry must be a mapping or a list of model objects.')


def _resolve_registry_path(raw_path: str) -> Path:
    path = Path(raw_path)
    if not path.is_absolute():
        path = (_ROOT / path).resolve()
    return path


@lru_cache()
def load_settings() -> ServerSettings:
    """Load typed settings from `realai.toml`, models/providers yaml, and profiles."""
    base = _load_toml_file(_ROOT / 'realai.toml')
    server = base.get('server', {}) if isinstance(base.get('server', {}), dict) else {}
    settings = ServerSettings(
        profile=str(server.get('profile', 'default')),
        provider=str(server.get('provider', 'local')),
        default_chat_model=str(server.get('default_chat_model', 'realai-1.0')),
        default_embedding_model=str(server.get('default_embedding_model', 'realai-embed')),
        enable_legacy_paths=bool(server.get('enable_legacy_paths', True)),
        model_registry_path=str(server.get('model_registry_path', str(_DEFAULT_REGISTRY_PATH))),
    )
    settings.profiles = _read_profiles()
    settings.providers = _load_yaml_file(_ROOT / 'providers.yaml')
    _validate_settings(settings)
    return settings


def _validate_settings(settings: ServerSettings) -> None:
    if not settings.default_chat_model:
        raise ValueError('server.default_chat_model is required.')
    if not settings.default_embedding_model:
        raise ValueError('server.default_embedding_model is required.')
    providers = settings.providers.get('providers', settings.providers)
    if providers and not isinstance(providers, dict):
        raise ValueError('providers.yaml must define an object of providers.')


@lru_cache()
def load_registry() -> Dict[str, Dict[str, Any]]:
    """Load model registry from configuration and normalize it."""
    settings = load_settings()
    registry_path = _resolve_registry_path(settings.model_registry_path)
    data = None
    if registry_path.exists():
        if registry_path.suffix.lower() in ('.yaml', '.yml'):
            data = _load_yaml_file(registry_path)
        else:
            data = json.loads(registry_path.read_text(encoding='utf-8'))
    else:
        models_path = _ROOT / 'models.yaml'
        if models_path.exists():
            data = _load_yaml_file(models_path)
    if not data:
        data = _default_registry()
    registry = _coerce_registry(data)
    providers = settings.providers.get('providers', settings.providers)
    if isinstance(providers, dict):
        for model_id, cfg in registry.items():
            provider = cfg.get('provider')
            if provider and provider not in providers:
                raise ValueError('Model {0} references unknown provider {1}.'.format(model_id, provider))
    return registry


def get_model_config(name: str, resolve_weights: bool = False) -> Dict[str, Any]:
    """Return the configuration for a registered model."""
    registry = load_registry()
    if name not in registry:
        raise ValueError('Unknown model {0}'.format(name))
    config = copy.deepcopy(registry[name])
    config.setdefault('id', name)
    if resolve_weights and config.get('type') == 'chat':
        resolved_path, enriched = resolve_inference_gguf_path(name, config)
        config['path'] = resolved_path
        for key, value in enriched.items():
            if key.startswith('weight') or key == 'resolved_gguf':
                config[key] = value
    elif config.get('type') == 'chat':
        from ..model_assets import _resolve_configured_path, resolve_realai_gguf

        if is_realai_owned_model(name, config) and name not in ('realai-embed', 'realai-vision'):
            gguf, diag = resolve_realai_gguf(name, str(config.get('path', name)))
            config['weight_diagnostics'] = diag
            config['weights_ready'] = gguf is not None
        else:
            raw_path = str(config.get('path', ''))
            if raw_path.endswith('.gguf'):
                resolved = _resolve_configured_path(raw_path)
                config['weights_ready'] = resolved is not None
            else:
                config['weights_ready'] = False
    return config


def list_models() -> List[str]:
    """List all registered models."""
    return sorted(load_registry().keys())


def list_model_objects() -> List[Dict[str, Any]]:
    """Return provider-style model objects for `/v1/models` responses."""
    data = []
    for model_id in list_models():
        cfg = get_model_config(model_id)
        row = {
            'id': model_id,
            'object': 'model',
            'owned_by': cfg.get('owned_by', 'realai'),
            'type': cfg.get('type', 'chat'),
            'backend': cfg.get('backend', 'unknown'),
            'context_length': cfg.get('context_length'),
            'embedding_dimensions': cfg.get('embedding_dimensions'),
            'capabilities': cfg.get('capabilities', []),
        }
        if 'weights_ready' in cfg:
            row['weights_ready'] = cfg['weights_ready']
        if cfg.get('weight_diagnostics'):
            row['weight_status'] = cfg['weight_diagnostics'].get('status')
        data.append(row)
    return data

"""
Robust, strict protocol for weak local models (ReAct-style over text).

Design goals (per code review):
- Extremely small, testable surface.
- Rigid output contract that small models can hit reliably.
- Multiple parse strategies (fenced JSON, TOOL:/ARGS:, loose DONE).
- Few-shot examples in the prompt.
- Helpers for "retry with exact format".
- No global side effects.

The contract the model must follow:
  TOOL: tool_name
  ARGS: {json object}

or

  DONE: short summary of what was accomplished

Only one action per turn. Read before you edit. Prefer small verifiable changes.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import Any, Dict, Optional, Tuple

# The canonical system instructions injected for self-build tasks.
# Keep this tight — small models do better with strict, short rules + examples.
BASE_RULES = """You are RealAI Self-Builder running 100% locally on GGUF weights.
Your only job is to improve this RealAI repository using the tools below.

CRITICAL INSTRUCTIONS - FOLLOW EXACTLY OR YOU WILL FAIL:
- Output NOTHING except exactly one TOOL block or one DONE block.
- Your entire response must start with "TOOL:" or "DONE:" and contain nothing else.
- Use exactly ONE tool per turn.
- ALWAYS read_file before any search_replace on that file.
- After receiving an OBSERVATION, immediately output the next action in the exact format.
- When the task is 100% complete (you verified with run_terminal_command that tests pass and the change is correct), output DONE.

Allowed tools: read_file, list_dir, grep, search_replace, run_terminal_command

EXACT OUTPUT FORMAT (copy character for character, no extra spaces or lines):

TOOL: read_file
ARGS: {"target_file": "realai/agent_protocol.py", "limit": 20}

DONE: Made the parser stricter and added test for tuple handling. All tests now pass.

If you output anything except the above format, the system will treat it as failure and send you an error.
"""

# A couple of high-signal few-shot examples. Small models copy style well.
FEW_SHOTS = """
Example 1:
User: Add a unit test for the new parser helper.
Assistant:
TOOL: read_file
ARGS: {"target_file": "tests/test_agent_protocol.py", "limit": 20}

Example 2 (after receiving an observation):
OBSERVATION: {"content": "def parse..."}
Assistant:
TOOL: search_replace
ARGS: {"file_path": "realai/agent_protocol.py", "old_string": "old buggy line", "new_string": "fixed line"}

Example 3 (after observation, using list_dir):
OBSERVATION: {"path": "realai", "entries": [{"name": "server", "type": "dir"}, ...]}
Assistant:
TOOL: list_dir
ARGS: {"target_directory": "realai/training"}

Example 4 (task complete):
Assistant:
DONE: Added the missing parser test case and verified with unittest. 7 tests passing.
"""

def build_system_prompt(workspace: str, extra_rules: str = "") -> str:
    ws = f"Workspace root: {workspace}\n"
    return ws + BASE_RULES + (extra_rules + "\n" if extra_rules else "") + "\nExamples:\n" + FEW_SHOTS


@dataclass
class ParsedAction:
    tool: Optional[str] = None
    args: Optional[Dict[str, Any]] = None
    done: Optional[str] = None
    raw: str = ""


def _strip_prefixes(text: str) -> str:
    t = text.strip()
    # Common model echoes / prefixes on Windows + llama.cpp
    t = re.sub(r"^[\s:>*•\-]+", "", t)
    t = re.sub(r"^(user|assistant|system)\s*:\s*", "", t, flags=re.IGNORECASE)
    t = re.sub(r"^[\s:]+", "", t)
    return t.strip()


def parse_agent_reply(text: str) -> ParsedAction:
    """
    Robust multi-strategy parser.
    Order of preference:
      1. Fenced JSON block containing {"tool": "...", "args": {...}} or {"done": "..."}
      2. TOOL: name \n ARGS: {json}
      3. DONE: summary  (anywhere, after stripping junk)
    Returns ParsedAction with exactly one of (tool+args) or done set.
    """
    if not text or not text.strip():
        return ParsedAction(raw=text)

    raw = text
    cleaned = _strip_prefixes(text)

    # 1. Fenced JSON (most reliable when model cooperates)
    fence = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", cleaned, re.DOTALL | re.IGNORECASE)
    if fence:
        try:
            obj = json.loads(fence.group(1))
            if isinstance(obj, dict):
                if obj.get("tool"):
                    return ParsedAction(tool=str(obj["tool"]), args=obj.get("args") or obj.get("arguments") or {}, raw=raw)
                if obj.get("done") or obj.get("DONE"):
                    return ParsedAction(done=str(obj.get("done") or obj.get("DONE")).strip(), raw=raw)
        except json.JSONDecodeError:
            pass

    # 2. Classic TOOL / ARGS (our primary training target)
    tool_m = re.search(r"TOOL:\s*([a-zA-Z0-9_\-]+)", cleaned, re.IGNORECASE)
    args_m = re.search(r"ARGS:\s*(\{.*\})", cleaned, re.DOTALL | re.IGNORECASE)
    if tool_m and args_m:
        try:
            args = json.loads(args_m.group(1))
            if isinstance(args, dict):
                return ParsedAction(tool=tool_m.group(1).strip(), args=args, raw=raw)
        except json.JSONDecodeError:
            pass

    # 3. DONE anywhere (after tool attempts failed)
    done_m = re.search(r"DONE:\s*(.+?)(?:\n|$)", cleaned, re.IGNORECASE | re.DOTALL)
    if done_m:
        summary = done_m.group(1).strip().split("\n")[0].strip()
        if summary:
            return ParsedAction(done=summary, raw=raw)

    # Nothing recognizable
    return ParsedAction(raw=raw)


def format_retry_message(last_raw: str, hint: str = "") -> str:
    """Message to feed back to the model when it produced unparseable output."""
    base = (
        "Your previous reply was not in the exact required format.\n"
        "Output ONLY one of these (nothing else):\n\n"
        "TOOL: tool_name\n"
        'ARGS: {"param": "value"}\n\n'
        "or\n\n"
        "DONE: short summary here\n\n"
    )
    if hint:
        base += f"Hint: {hint}\n"
    if last_raw:
        base += f"Previous (do not repeat this style):\n{last_raw[:600]}\n"
    return base


def is_done(action: ParsedAction) -> bool:
    if isinstance(action, (list, tuple)):
        # Legacy 3-tuple compat: (tool, args, done)
        if len(action) >= 3:
            return bool(action[2])
        return False
    return bool(getattr(action, "done", None) and not getattr(action, "tool", None))


def is_tool_call(action: ParsedAction) -> bool:
    if isinstance(action, (list, tuple)):
        if len(action) >= 3:
            return bool(action[0]) and bool(action[1])
        return False
    return bool(getattr(action, "tool", None) and getattr(action, "args", None) is not None)


# Small set of canonical tool names we expect for self-build.
REPO_TOOLS = {"read_file", "list_dir", "grep", "search_replace", "run_terminal_command"}


def normalize_repo_args(tool: str, args: Dict[str, Any]) -> Dict[str, Any]:
    """Map common model mistakes to the exact param names our handlers expect."""
    a = dict(args or {})
    if tool == "read_file":
        if "target_file" not in a:
            for k in ("file_path", "path", "file"):
                if k in a:
                    a["target_file"] = a.pop(k)
                    break
    elif tool == "list_dir":
        if "target_directory" not in a:
            for k in ("path", "dir", "directory", "target_dir", "folder"):
                if k in a:
                    a["target_directory"] = a.pop(k)
                    break
    elif tool == "search_replace":
        if "file_path" not in a:
            for k in ("target_file", "path"):
                if k in a:
                    a["file_path"] = a.pop(k)
                    break
    elif tool == "grep":
        if "path" not in a and "target_directory" in a:
            a["path"] = a.pop("target_directory")
    return a

"""End-to-end native model pipeline: data → fine-tune → GGUF → eval."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any, Dict, List, Optional

from realai.model_assets import list_realai_weight_status

from .build_datasets import build_dataset_bundle
from .eval import evaluate_instruction_dataset, evaluate_native_server
from .export_gguf import export_from_hf, publish_gguf
from .finetune import build_finetune_plan, run_finetune


def run_stage(stage: str, **kwargs) -> Dict[str, Any]:
    if stage == "datasets":
        return build_dataset_bundle(kwargs.get("data_dir"))
    if stage == "plan":
        return build_finetune_plan(kwargs.get("data_dir"), kwargs.get("model_id", "realai-1.0-instruct"))
    if stage == "finetune":
        return run_finetune(
            data_dir=kwargs.get("data_dir"),
            model_id=kwargs.get("model_id", "realai-1.0-instruct"),
            max_steps=int(kwargs.get("max_steps", 50)),
        )
    if stage == "export":
        model_id = kwargs.get("model_id", "realai-1.0-instruct")
        hf_dir = kwargs.get("hf_dir")
        gguf = kwargs.get("gguf")

        if gguf:
            return publish_gguf(
                Path(gguf),
                model_id,
                quant_label=kwargs.get("quant", "Q4_K_M"),
                copy_to=kwargs.get("copy_to") or ["realai-1.0"],
            )

        # If user explicitly gave hf-dir or the merged dir from a previous finetune exists, use HF path
        if hf_dir:
            return export_from_hf(
                Path(hf_dir),
                model_id,
                quant=kwargs.get("quant", "Q4_K_M"),
                copy_to=kwargs.get("copy_to") or ["realai-1.0"],
            )

        plan = build_finetune_plan(model_id=model_id)
        auto_hf = Path(plan["hf_output_dir"]) / "merged"
        if auto_hf.exists():
            return export_from_hf(
                auto_hf,
                model_id,
                quant=kwargs.get("quant", "Q4_K_M"),
                copy_to=kwargs.get("copy_to") or ["realai-1.0"],
            )

        # No HF checkpoint. Fall back to publishing an existing GGUF (bootstrap path).
        # Try the common dev reference GGUF first, then any .gguf under models/
        from .bootstrap_weights import discover_local_gguf
        candidates = discover_local_gguf()
        if candidates:
            # Prefer the Llama dev one if present, else the first one
            chosen = None
            for c in candidates:
                if "Llama" in c.name or "llama" in c.name:
                    chosen = c
                    break
            if not chosen:
                chosen = candidates[0]
            return publish_gguf(
                chosen,
                model_id,
                quant_label=kwargs.get("quant", "Q4_K_M"),
                copy_to=kwargs.get("copy_to") or ["realai-1.0"],
            )

        # Nothing available — give clear guidance
        raise FileNotFoundError(
            "No fine-tuned HF model and no existing GGUF found for export.\n"
            "Options:\n"
            "  1. Run finetune first:  python -m realai.training.pipeline --stage finetune\n"
            "  2. Brand an existing GGUF (recommended for bootstrap):  python -m realai.training.bootstrap_weights\n"
            "  3. Or pass an explicit GGUF:  python -m realai.training.pipeline --stage export --gguf path/to/your.gguf\n"
            f"Expected HF dir (after finetune): {auto_hf}\n"
            "Existing GGUFs discovered under models/: " + (", ".join(str(c) for c in candidates) if candidates else "none")
        )
    if stage == "eval":
        out: Dict[str, Any] = {"dataset": evaluate_instruction_dataset()}
        if kwargs.get("server"):
            out["server"] = evaluate_native_server(
                kwargs.get("server", "http://127.0.0.1:8000"),
                kwargs.get("model_id", "realai-1.0-instruct"),
            )
        out["weights"] = list_realai_weight_status()
        return out
    if stage == "status":
        return {"weights": list_realai_weight_status()}
    if stage == "ingest":
        from .extract_from_agent_tools import extract_all_training_sources

        return extract_all_training_sources(kwargs.get("data_dir"))
    if stage == "bootstrap":
        from .bootstrap_weights import bootstrap_native_weights

        return bootstrap_native_weights(
            model_id=kwargs.get("model_id", "realai-1.0-instruct"),
            source=kwargs.get("gguf"),
        )
    raise ValueError(f"Unknown stage: {stage}")


def run_all(model_id: str = "realai-1.0-instruct", max_steps: int = 50, server: Optional[str] = None) -> Dict[str, Any]:
    report: Dict[str, Any] = {"stages": {}}
    for stage in ("datasets", "finetune", "export", "eval"):
        try:
            report["stages"][stage] = run_stage(
                stage,
                model_id=model_id,
                max_steps=max_steps,
                server=server or "http://127.0.0.1:8000",
            )
        except Exception as exc:
            report["stages"][stage] = {"status": "error", "error": str(exc)}
            report["stopped_at"] = stage
            break
    return report


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="RealAI native model training pipeline")
    parser.add_argument(
        "--stage",
        choices=["datasets", "plan", "finetune", "export", "eval", "status", "bootstrap", "ingest", "all"],
        default="status",
    )
    parser.add_argument("--model-id", default="realai-1.0-instruct")
    parser.add_argument("--data-dir", default=None)
    parser.add_argument("--max-steps", type=int, default=50)
    parser.add_argument("--hf-dir", default=None)
    parser.add_argument("--gguf", default=None, help="Skip HF; publish an existing GGUF file")
    parser.add_argument("--quant", default="Q4_K_M")
    parser.add_argument("--server", default="http://127.0.0.1:8000")
    return parser


def main(argv: Optional[List[str]] = None) -> Dict[str, Any]:
    args = build_parser().parse_args(argv)
    if args.stage == "all":
        result = run_all(model_id=args.model_id, max_steps=args.max_steps, server=args.server)
    else:
        result = run_stage(
            args.stage,
            data_dir=args.data_dir,
            model_id=args.model_id,
            max_steps=args.max_steps,
            hf_dir=args.hf_dir,
            gguf=args.gguf,
            quant=args.quant,
            server=args.server,
        )
    print(json.dumps(result, indent=2, default=str))
    return result


if __name__ == "__main__":
    main()

"""Discover vendored or system llama.cpp binaries for export/inference."""

from __future__ import annotations

import os
import shutil
import sys
from pathlib import Path
from typing import List, Optional

_REPO_ROOT = Path(__file__).resolve().parents[2]


def repo_root() -> Path:
    return _REPO_ROOT


def _candidates(names: List[str], extra_dirs: Optional[List[Path]] = None) -> List[Path]:
    paths: List[Path] = []
    for name in names:
        found = shutil.which(name)
        if found:
            paths.append(Path(found))
    dirs = list(extra_dirs or [])
    dirs.extend(
        [
            _REPO_ROOT / "vendor" / "llama.cpp" / "b4400",
            _REPO_ROOT / "vendor" / "llama.cpp" / "b9663" / "llama-b9663",
        ]
    )
    env_root = os.environ.get("REALAI_LLAMA_CPP_ROOT", "").strip()
    if env_root:
        dirs.append(Path(env_root).expanduser())
        dirs.append(Path(env_root).expanduser() / "build" / "bin")
        dirs.append(Path(env_root).expanduser() / "build" / "bin" / "Release")
    for directory in dirs:
        if not directory.is_dir():
            continue
        for name in names:
            for variant in (name, f"{name}.exe"):
                candidate = directory / variant
                if candidate.is_file():
                    paths.append(candidate)
    return paths


def find_llama_quantize() -> Optional[Path]:
    for path in _candidates(["llama-quantize", "quantize"]):
        if path.is_file():
            return path
    return None


def find_llama_cli() -> Optional[Path]:
    for path in _candidates(["llama-cli", "llama"]):
        if path.is_file():
            return path
    return None


def find_convert_hf_script() -> Optional[Path]:
    """Locate convert_hf_to_gguf.py from a llama.cpp checkout."""
    env = os.environ.get("REALAI_LLAMA_CPP_ROOT", "").strip()
    search_roots: List[Path] = []
    if env:
        search_roots.append(Path(env).expanduser())
    search_roots.extend(
        [
            _REPO_ROOT / "vendor" / "llama.cpp",
            Path.home() / "llama.cpp",
            Path("C:/llama.cpp"),
        ]
    )
    rel_paths = [
        Path("convert_hf_to_gguf.py"),
        Path("tools") / "convert_hf_to_gguf.py",
        Path("gguf-py") / "gguf" / "scripts" / "convert_hf_to_gguf.py",
    ]
    for root in search_roots:
        if not root.is_dir():
            continue
        for rel in rel_paths:
            candidate = (root / rel).resolve()
            if candidate.is_file():
                return candidate
    return None


def python_for_llama_convert() -> str:
    return os.environ.get("REALAI_PYTHON", sys.executable)

"""Install RealAI-branded weights from on-disk GGUF you already have (no F16/HF)."""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
from typing import Any, Dict, List, Optional

from realai.model_assets import models_root, repo_root, resolve_realai_gguf

from .export_gguf import publish_gguf

# Dev/reference GGUF in repo root — used only to stand up native inference until trained weights exist.
_DEFAULT_SOURCES: Dict[str, str] = {
    "realai-1.0-instruct": "models/Llama-3.2-1B-Instruct-Q4_K_M.gguf",
    "realai-1.0": "models/Llama-3.2-1B-Instruct-Q4_K_M.gguf",
}


def _resolve_source(path_str: str) -> Optional[Path]:
    raw = Path(path_str).expanduser()
    if raw.is_file():
        return raw.resolve()
    for base in (repo_root(), models_root(), Path.cwd()):
        joined = (base / raw).resolve()
        if joined.is_file():
            return joined
    return None


def discover_local_gguf() -> List[Path]:
    root = models_root()
    found: List[Path] = []
    for pattern in ("*.gguf", "*/*.gguf"):
        found.extend(sorted(root.glob(pattern)))
    # De-dupe; skip anything already under realai-*/weights with branded name
    unique: List[Path] = []
    seen = set()
    for path in found:
        key = str(path.resolve())
        if key in seen:
            continue
        if "realai-" in path.parts and "weights" in path.parts:
            if path.name.startswith("realai-"):
                continue
        seen.add(key)
        unique.append(path.resolve())
    return unique


def bootstrap_native_weights(
    *,
    model_id: str = "realai-1.0-instruct",
    source: Optional[str] = None,
    quant: str = "Q4_K_M",
    copy_to: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """Copy an existing quantized GGUF into models/<id>/weights/ with RealAI naming."""
    src_path: Optional[Path] = None
    if source:
        src_path = _resolve_source(source)
    if src_path is None:
        default = os.environ.get("REALAI_BOOTSTRAP_GGUF", "").strip() or _DEFAULT_SOURCES.get(
            model_id, _DEFAULT_SOURCES["realai-1.0-instruct"]
        )
        src_path = _resolve_source(default)
    if src_path is None:
        candidates = discover_local_gguf()
        if candidates:
            src_path = candidates[0]

    if src_path is None:
        return {
            "status": "no_source",
            "message": "No .gguf found. Place a file under models/ or set REALAI_BOOTSTRAP_GGUF.",
            "candidates_checked": list(_DEFAULT_SOURCES.values()),
        }

    extras = list(copy_to or [])
    if model_id == "realai-1.0-instruct" and "realai-1.0" not in extras:
        extras.append("realai-1.0")
    # Dev layout: overseer uses the same bootstrap GGUF until a dedicated overseer checkpoint exists.
    if "realai-overseer" not in extras:
        extras.append("realai-overseer")

    result = publish_gguf(
        src_path,
        model_id,
        quant_label=quant,
        copy_to=extras,
        metadata={
            "bootstrap": True,
            "bootstrap_source": str(src_path),
            "note": "Dev bootstrap from existing GGUF; replace with fine-tuned RealAI weights when ready.",
        },
    )
    result["bootstrap_source"] = str(src_path)
    return result


def ensure_native_weights_if_missing(
    model_id: str = "realai-1.0-instruct",
) -> Dict[str, Any]:
    """No-op when weights exist; otherwise run bootstrap from env/default GGUF."""
    gguf, _diag = resolve_realai_gguf(model_id)
    if gguf is not None:
        return {"status": "already_ready", "model_id": model_id, "gguf": str(gguf)}
    if os.environ.get("REALAI_AUTO_BOOTSTRAP", "").strip().lower() not in ("1", "true", "yes"):
        return {"status": "missing", "model_id": model_id, "hint": "Set REALAI_AUTO_BOOTSTRAP=1 or run bootstrap_weights"}
    return bootstrap_native_weights(model_id=model_id)


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Bootstrap RealAI native GGUF from files you already have")
    parser.add_argument("--model-id", default="realai-1.0-instruct")
    parser.add_argument("--source", default=None, help="Path to any .gguf (Q4/Q5 OK; F16 not required)")
    parser.add_argument("--quant", default="Q4_K_M", help="Label for output filename only when copying Q4/Q5")
    parser.add_argument("--list", action="store_true", help="List discoverable GGUF under models/")
    return parser


def main(argv: Optional[List[str]] = None) -> Dict[str, Any]:
    args = build_parser().parse_args(argv)
    if args.list:
        payload = {"discovered": [str(p) for p in discover_local_gguf()]}
        print(json.dumps(payload, indent=2))
        return payload
    print("[realai] Bootstrapping native weights. If you get a 'user-mapped section' error on Windows,")
    print("         stop the inference server (the terminal running `python -m realai.server.app`) first.")
    result = bootstrap_native_weights(model_id=args.model_id, source=args.source, quant=args.quant)
    print(json.dumps(result, indent=2, default=str))
    return result


if __name__ == "__main__":
    main()

